function createBaseErpBatch(): ErpBatch {
  return {
    batchId: 0,
    period: "",
    mode: 0,
    status: 0,
    seq: 0,
    createdBy: "",
    createdAt: "",
    updatedAt: "",
    summaryJson: "",
    progress: 0,
    allowedActions: [],
    failedReason: "",
  };
}

export const ErpBatch: MessageFns<ErpBatch> = {
  encode(message: ErpBatch, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.batchId !== 0) {
      writer.uint32(8).int64(message.batchId);
    }
    if (message.period !== "") {
      writer.uint32(18).string(message.period);
    }
    if (message.mode !== 0) {
      writer.uint32(24).int32(message.mode);
    }
    if (message.status !== 0) {
      writer.uint32(32).int32(message.status);
    }
    if (message.seq !== 0) {
      writer.uint32(40).int32(message.seq);
    }
    if (message.createdBy !== "") {
      writer.uint32(50).string(message.createdBy);
    }
    if (message.createdAt !== "") {
      writer.uint32(58).string(message.createdAt);
    }
    if (message.updatedAt !== "") {
      writer.uint32(66).string(message.updatedAt);
    }
    if (message.summaryJson !== "") {
      writer.uint32(74).string(message.summaryJson);
    }
    if (message.progress !== 0) {
      writer.uint32(80).int32(message.progress);
    }
    for (const v of message.allowedActions) {
      writer.uint32(90).string(v!);
    }
    if (message.failedReason !== "") {
      writer.uint32(98).string(message.failedReason);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ErpBatch {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseErpBatch();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.batchId = longToNumber(reader.int64());
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.period = reader.string();
          continue;
        }
        case 3: {
          if (tag !== 24) {
            break;
          }

          message.mode = reader.int32() as any;
          continue;
        }
        case 4: {
          if (tag !== 32) {
            break;
          }

          message.status = reader.int32() as any;
          continue;
        }
        case 5: {
          if (tag !== 40) {
            break;
          }

          message.seq = reader.int32();
          continue;
        }
        case 6: {
          if (tag !== 50) {
            break;
          }

          message.createdBy = reader.string();
          continue;
        }
        case 7: {
          if (tag !== 58) {
            break;
          }

          message.createdAt = reader.string();
          continue;
        }
        case 8: {
          if (tag !== 66) {
            break;
          }

          message.updatedAt = reader.string();
          continue;
        }
        case 9: {
          if (tag !== 74) {
            break;
          }

          message.summaryJson = reader.string();
          continue;
        }
        case 10: {
          if (tag !== 80) {
            break;
          }

          message.progress = reader.int32();
          continue;
        }
        case 11: {
          if (tag !== 90) {
            break;
          }

          message.allowedActions.push(reader.string());
          continue;
        }
        case 12: {
          if (tag !== 98) {
            break;
          }

          message.failedReason = reader.string();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): ErpBatch {
    return {
      batchId: isSet(object.batchId)
        ? globalThis.Number(object.batchId)
        : isSet(object.batch_id)
        ? globalThis.Number(object.batch_id)
        : 0,
      period: isSet(object.period) ? globalThis.String(object.period) : "",
      mode: isSet(object.mode) ? erpBatchModeFromJSON(object.mode) : 0,
      status: isSet(object.status) ? erpBatchStatusFromJSON(object.status) : 0,
      seq: isSet(object.seq) ? globalThis.Number(object.seq) : 0,
      createdBy: isSet(object.createdBy)
        ? globalThis.String(object.createdBy)
        : isSet(object.created_by)
        ? globalThis.String(object.created_by)
        : "",
      createdAt: isSet(object.createdAt)
        ? globalThis.String(object.createdAt)
        : isSet(object.created_at)
        ? globalThis.String(object.created_at)
        : "",
      updatedAt: isSet(object.updatedAt)
        ? globalThis.String(object.updatedAt)
        : isSet(object.updated_at)
        ? globalThis.String(object.updated_at)
        : "",
      summaryJson: isSet(object.summaryJson)
        ? globalThis.String(object.summaryJson)
        : isSet(object.summary_json)
        ? globalThis.String(object.summary_json)
        : "",
      progress: isSet(object.progress) ? globalThis.Number(object.progress) : 0,
      allowedActions: globalThis.Array.isArray(object?.allowedActions)
        ? object.allowedActions.map((e: any) => globalThis.String(e))
        : globalThis.Array.isArray(object?.allowed_actions)
        ? object.allowed_actions.map((e: any) => globalThis.String(e))
        : [],
      failedReason: isSet(object.failedReason)
        ? globalThis.String(object.failedReason)
        : isSet(object.failed_reason)
        ? globalThis.String(object.failed_reason)
        : "",
    };
  },

  toJSON(message: ErpBatch): unknown {
    const obj: any = {};
    if (message.batchId !== 0) {
      obj.batchId = Math.round(message.batchId);
    }
    if (message.period !== "") {
      obj.period = message.period;
    }
    if (message.mode !== 0) {
      obj.mode = erpBatchModeToJSON(message.mode);
    }
    if (message.status !== 0) {
      obj.status = erpBatchStatusToJSON(message.status);
    }
    if (message.seq !== 0) {
      obj.seq = Math.round(message.seq);
    }
    if (message.createdBy !== "") {
      obj.createdBy = message.createdBy;
    }
    if (message.createdAt !== "") {
      obj.createdAt = message.createdAt;
    }
    if (message.updatedAt !== "") {
      obj.updatedAt = message.updatedAt;
    }
    if (message.summaryJson !== "") {
      obj.summaryJson = message.summaryJson;
    }
    if (message.progress !== 0) {
      obj.progress = Math.round(message.progress);
    }
    if (message.allowedActions?.length) {
      obj.allowedActions = message.allowedActions;
    }
    if (message.failedReason !== "") {
      obj.failedReason = message.failedReason;
    }
    return obj;
  },

  create(base?: DeepPartial<ErpBatch>): ErpBatch {
    return ErpBatch.fromPartial(base ?? {});
  },
  fromPartial(object: DeepPartial<ErpBatch>): ErpBatch {
    const message = createBaseErpBatch();
    message.batchId = object.batchId ?? 0;
    message.period = object.period ?? "";
    message.mode = object.mode ?? 0;
    message.status = object.status ?? 0;
    message.seq = object.seq ?? 0;
    message.createdBy = object.createdBy ?? "";
    message.createdAt = object.createdAt ?? "";
    message.updatedAt = object.updatedAt ?? "";
    message.summaryJson = object.summaryJson ?? "";
    message.progress = object.progress ?? 0;
    message.allowedActions = object.allowedActions?.map((e) => e) || [];
    message.failedReason = object.failedReason ?? "";
    return message;
  },
};

